class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        pow_bank = set()
        for i in range(len(s)):
            pow_bank.add(pow(5, i))

        dp = [float('inf')] * (len(s) + 1)
        dp[len(s)] = 0

        for i in range(len(s) - 1, -1, -1):
            if s[i] == '0':
                continue

            for j in range(i, len(s)):
                dec = int(s[i:j + 1], 2)
                if dec in pow_bank:
                    dp[j] = min(dp[j + 1] + 1, dp[j])

        if dp[0] == float('inf'):
            return -1
        return dp[0]

